public class Chaining {
    static class DaoException extends RuntimeException {
        DaoException(String m, Throwable c) { super(m, c); }
    }
    static class ServiceException extends RuntimeException {
        ServiceException(String m, Throwable c) { super(m, c); }
    }
    static void dao() { throw new DaoException("查询失败", new IllegalStateException("表不存在")); }
    static void service() {
        try { dao(); }
        catch (DaoException e) { throw new ServiceException("加载用户失败", e); }
    }
    public static void main(String[] args) {
        try { service(); }
        catch (ServiceException e) {
            System.out.println(e.getMessage());
            System.out.println("原因: " + e.getCause().getMessage());
            System.out.println("根因: " + e.getCause().getCause().getMessage());
        }
    }
}

public class Suppressed {
    static class Res implements AutoCloseable {
        public void work() { throw new IllegalStateException("工作失败"); }
        public void close() { throw new IllegalArgumentException("关闭失败"); }
    }
    public static void main(String[] args) {
        try (Res r = new Res()) { r.work(); }
        catch (Exception e) {
            System.out.println("主异常: " + e.getMessage());
            for (Throwable s : e.getSuppressed()) System.out.println("抑制: " + s.getMessage());
        }
    }
}

