public class CustomEx {
    static class BizException extends RuntimeException {
        private final String code;
        BizException(String code, String msg) { super(msg); this.code = code; }
        BizException(String code, String msg, Throwable cause) { super(msg, cause); this.code = code; }
        public String getCode() { return code; }
    }
    static class InsufficientBalanceException extends BizException {
        private final long required;
        InsufficientBalanceException(long required, long available) {
            super("BALANCE", "余额不足，需要 " + required + "，实际 " + available);
            this.required = required;
        }
        public long getRequired() { return required; }
    }
    public static void main(String[] args) {
        try { throw new InsufficientBalanceException(100, 30); }
        catch (BizException e) { System.out.println(e.getCode() + " " + e.getMessage()); }
    }
}

public class Translate {
    static class DataAccessException extends RuntimeException {
        DataAccessException(String m, Throwable c) { super(m, c); }
    }
    static class UserDao {
        String find(long id) { throw new IllegalStateException("connection reset"); }
    }
    static class UserService {
        private final UserDao dao = new UserDao();
        String load(long id) {
            try { return dao.find(id); }
            catch (RuntimeException e) {
                throw new DataAccessException("查询用户失败, id=" + id, e);
            }
        }
    }
    public static void main(String[] args) {
        try { new UserService().load(7); }
        catch (DataAccessException e) {
            System.out.println(e.getMessage());
            System.out.println("根因: " + e.getCause().getMessage());
        }
    }
}

public class Perf {
    static class Light extends RuntimeException {
        Light(String m) { super(m, null, false, false); }
    }
    public static void main(String[] args) {
        long t1 = System.nanoTime();
        for (int i = 0; i < 100000; i++) { try { throw new RuntimeException("x"); } catch (RuntimeException e) { } }
        long t2 = System.nanoTime();
        for (int i = 0; i < 100000; i++) { try { throw new Light("x"); } catch (RuntimeException e) { } }
        long t3 = System.nanoTime();
        System.out.println("heavy " + (t2 - t1) / 1000000 + "ms");
        System.out.println("light " + (t3 - t2) / 1000000 + "ms");
    }
}

