// 编译器检查的层级关系
// Throwable
//   ├── Error（不管）
//   └── Exception
//         ├── IOException            ← 受检，必须处理或声明
//         ├── InterruptedException   ← 受检
//         └── RuntimeException       ← 非受检，编译器放行
//               ├── NullPointerException
//               ├── ArithmeticException（除以零）
//               └── NumberFormatException

try {
  Foo f = x.doRiskyThing();  // 若这里抛异常
  int b = f.getNum();        // 这行就不会执行（f 可能为 null）
} catch (Exception e) {
  System.out.println("failed");
}
System.out.println("We made it!");   // 无论成功失败都会执行

// 成功输出：We made it!
// 失败输出：failed 然后 We made it!

// 不用 finally：清理代码被迫写两遍
public void bakeBad() {
  try {
    turnOvenOn();
    x.bake();
    turnOvenOff();          // 成功路径要关
  } catch (BakingException e) {
    e.printStackTrace();
    turnOvenOff();          // 失败路径也要关（重复了）
  }
}

// 用 finally：清理逻辑只有一份
public void bakeGood() {
  try {
    turnOvenOn();
    x.bake();
  } catch (BakingException e) {
    e.printStackTrace();
  } finally {
    turnOvenOff();          // 无论成败，一定执行
  }
}

